// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

contract Bank {
    mapping(address => uint256) public balances;

    // Fonction pour déposer de l'ETH dans le contrat
    function deposit() public payable {
        balances[msg.sender] += msg.value;
    }

    // Fonction pour retirer des ETH
    function withdraw(uint256 _amount) public {
        require(balances[msg.sender] >= _amount, "Pas assez de fonds");

        // Envoi d'ETH avant de mettre à jour le solde
        payable(msg.sender).transfer(_amount);

        // Mise à jour du solde après le transfert
        balances[msg.sender] -= _amount;
    }
}
